// Simulated Load Balancer logic
const servers = [
  { name: 'Server A', active: true },
  { name: 'Server B', active: true },
  { name: 'Server C', active: false } // Crashed!
];

let currentIndex = 0;

function loadBalancer() {
  // 1. Find the next server in the list (Round Robin)
  let target = servers[currentIndex];

  // 2. Health Check! If crashed, skip it.
  if (!target.active) {
    console.log(`[LB]: ${target.name} is DEAD. Skipping...`);
    currentIndex = (currentIndex + 1) % servers.length;
    target = servers[currentIndex];
  }

  console.log(`[LB]: Routing user request to ${target.name}`);

  // Advance the index for the next request
  currentIndex = (currentIndex + 1) % servers.length;
}

console.log("Traffic Spike incoming!\n");
loadBalancer();
loadBalancer();
loadBalancer();
loadBalancer();
